package com.lmspilot.certificate.api;import com.lmspilot.contracts.EventTypes;import org.springframework.amqp.core.*;import org.springframework.context.annotation.*;@Configuration public class CertificateMessagingConfiguration{@Bean public Queue certificateQueue(){return new Queue("certificate.course-completed",true);}@Bean public Binding certificateBinding(Queue certificateQueue,TopicExchange domainEventExchange){return BindingBuilder.bind(certificateQueue).to(domainEventExchange).with(EventTypes.COURSE_COMPLETED);}}
